#!/usr/bin/env python3
"""Generate Arabic B1 Unit 02: complications, misunderstandings, and recovery."""
from __future__ import annotations
import json,re,unicodedata
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/"reading"/"arabic"/"b1"/"passages.jsonl";LEX=ROOT/"reading"/"lexicons"/"arabic.jsonl"
AR_DIAC=re.compile(r"[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]")
def norm(s):return AR_DIAC.sub("",unicodedata.normalize("NFC",s).replace("ـ","").strip())
PREFERRED={"سبب":"reason; cause","نتيجة":"result; outcome","حل":"solution","خطأ":"error; mistake","تفاصيل":"details","موقف":"situation; position","بديل":"alternative","تغيير":"change"}
def lexicon():
 d={}
 for l in LEX.read_text(encoding="utf-8").splitlines():
  if l.strip():r=json.loads(l);d.setdefault(norm(r.get("form","")),r)
 return d
def targets(forms,text,d):
 out=[]
 for f in forms:
  r=d.get(norm(f))
  if r:out.append({"id":f"ar-r{r['rank']}","form":f,"lemma":f,"part_of_speech":r.get("part_of_speech_source"),"intended_sense":PREFERRED[f],"register":"contemporary standard","variety":"MSA","context_strategy":["scenario_resolution","cause_consequence"],"first_introduced":True,"exposures_in_text":max(1,text.count(f)),"source_lexicon":r.get("source_file"),"source_rank":r["rank"],"beyond_base":False})
 return out
def qa(items):
 q=[];a=[]
 for i,(t,p,x,ids) in enumerate(items,1):
  z={"id":f"q{i}","type":t,"prompt":p,"answer_id":f"a{i}"};
  if ids:z["target_ids"]=ids
  q.append(z);a.append({"id":f"a{i}","question_id":f"q{i}","answer":x,"explanation":""})
 return q,a
